from __future__ import annotations

import hashlib
import typing

from .errors import PdaError
from .pubkey import Pubkey

__all__ = [
    "MAX_SEEDS",
    "MAX_SEED_LENGTH",
    "create_program_address",
    "find_program_address",
]

MAX_SEEDS = 16
MAX_SEED_LENGTH = 32

_PDA_MARKER = b"ProgramDerivedAddress"

# Ed25519 curve constants (RFC 8032).
_P = 2**255 - 19
_D = (-121665 * pow(121666, _P - 2, _P)) % _P
_SQRT_M1 = pow(2, (_P - 1) // 4, _P)


def _is_on_curve(data: bytes) -> bool:
    """Returns True iff `data` decodes to a valid ed25519 point (RFC 8032 §5.1.3)."""
    if len(data) != 32:
        return False
    y = int.from_bytes(data, "little")
    sign = y >> 255
    y &= (1 << 255) - 1
    if y >= _P:
        return False
    y2 = (y * y) % _P
    u = (y2 - 1) % _P
    v = (_D * y2 + 1) % _P
    # Compute the candidate square root x = (u/v) ** ((p + 3) / 8).
    x2 = (u * pow(v, _P - 2, _P)) % _P
    x = pow(x2, (_P + 3) // 8, _P)
    if (x * x) % _P != x2:
        x = (x * _SQRT_M1) % _P
    if (x * x) % _P != x2:
        return False
    if x == 0 and sign == 1:
        return False
    return True


def _check_seeds(seeds: typing.Sequence[bytes]) -> None:
    if len(seeds) > MAX_SEEDS:
        raise PdaError("too many seeds: %d (max %d)" % (len(seeds), MAX_SEEDS))
    for seed in seeds:
        if len(seed) > MAX_SEED_LENGTH:
            raise PdaError("seed too long: %d bytes (max %d)" % (len(seed), MAX_SEED_LENGTH))


def create_program_address(seeds: typing.Sequence[bytes], program_id: Pubkey) -> Pubkey:
    """Derives a program address from seeds; fails if it lands on the ed25519 curve."""
    _check_seeds(seeds)
    digest = hashlib.sha256()
    for seed in seeds:
        digest.update(bytes(seed))
    digest.update(program_id.to_bytes())
    digest.update(_PDA_MARKER)
    candidate = digest.digest()
    if _is_on_curve(candidate):
        raise PdaError("invalid seeds: the address falls on the ed25519 curve")
    return Pubkey(candidate)


def find_program_address(seeds: typing.Sequence[bytes], program_id: Pubkey) -> typing.Tuple[Pubkey, int]:
    """Finds the first off-curve program address, trying bump seeds 255 down to 0."""
    _check_seeds(seeds)
    for bump in range(255, -1, -1):
        try:
            return create_program_address([*seeds, bytes([bump])], program_id), bump
        except PdaError:
            continue
    raise PdaError("unable to find a viable program derived address bump")
